def solve_peak_calls(text):
    tokens = text.split()
    n = int(tokens[0])
    events = []
    for i in range(n):
        start, end = int(tokens[1 + 2 * i]), int(tokens[2 + 2 * i])
        events.append((start, 1))
        events.append((end, -1))
    events.sort()
    live = peak = when = 0
    for time, step in events:
        live += step
        if live > peak:
            peak, when = live, time
    return '%d %d' % (peak, when)
